//! Exact parity between [`SpacyTokenizer`] and spaCy 3.8's
//! `en_core_web_sm` 3.8.0 tokenizer.
//!
//! The fixture (`tests/fixtures/spacy_tokenizer_oracle.json`) is checked in
//! and was generated by
//! `crates/boostr-audio/tests/tools/kokoro_g2p_oracle/spacy_tokenizer_oracle.py`.
//! It covers the 388-sentence narration corpus and a stress set of URLs,
//! emails, emoticons, contractions, abbreviations, numbers, quotes, dashes,
//! Unicode punctuation and whitespace runs.
//!
//! Every text is checked for the token texts and the six lexical attributes
//! `tok2vec` embeds: `NORM`, `PREFIX`, `SUFFIX`, `SHAPE`, `SPACY` and
//! `IS_SPACE`. All mismatches print before the test fails.

use boostr_audio::g2p::spacy_tokenizer::{SpacyToken, SpacyTokenizer};
use serde::Deserialize;

mod common;
use common::load_json;

/// `[text, spacy, norm, prefix, suffix, shape, is_space]`.
type TokenRow = (String, bool, String, String, String, String, bool);

#[derive(Debug, Deserialize)]
struct Fixture {
    source: String,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    set: String,
    text: String,
    tokens: Vec<TokenRow>,
}

fn row(t: &SpacyToken) -> TokenRow {
    (
        t.text.clone(),
        t.spacy,
        t.norm.clone(),
        t.prefix.clone(),
        t.suffix.clone(),
        t.shape.clone(),
        t.is_space,
    )
}

#[test]
fn matches_spacy_en_core_web_sm() {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/spacy_tokenizer_oracle.json"
    );
    let fixture: Fixture = load_json(std::path::Path::new(path));
    assert!(!fixture.cases.is_empty(), "fixture must not be empty");

    let tokenizer =
        SpacyTokenizer::en_core_web_sm().unwrap_or_else(|e| panic!("SpacyTokenizer: {e}"));
    assert_eq!(
        tokenizer.source(),
        fixture.source,
        "the fixture and the embedded data come from different spaCy builds"
    );

    let mut failures = Vec::new();
    let mut exact = std::collections::BTreeMap::<&str, (usize, usize)>::new();
    for case in &fixture.cases {
        let got: Vec<TokenRow> = tokenizer.tokenize(&case.text).iter().map(row).collect();
        let entry = exact.entry(case.set.as_str()).or_default();
        entry.1 += 1;
        if got == case.tokens {
            entry.0 += 1;
            continue;
        }
        let mut report = format!("[{}] {:?}", case.set, case.text);
        let n = got.len().max(case.tokens.len());
        for i in 0..n {
            let (g, w) = (got.get(i), case.tokens.get(i));
            if g != w {
                report.push_str(&format!(
                    "\n  token {i}\n    rust:  {g:?}\n    spacy: {w:?}"
                ));
            }
        }
        failures.push(report);
    }
    for (set, (ok, total)) in &exact {
        println!("{set}: {ok}/{total} texts exact");
    }
    for f in &failures {
        println!("{f}");
    }
    assert!(
        failures.is_empty(),
        "{} of {} texts mismatched; see the output above",
        failures.len(),
        fixture.cases.len()
    );
}
